/* ═══════════════════════════════════════════════
   PRINCE MISTRY — PORTFOLIO JAVASCRIPT
═══════════════════════════════════════════════ */

/* ── PROFILE PHOTO (base64 injected at build) ── */
const PHOTO = "data:image/png;base64,";

/* ══════════════════════════════════════════
   DOM READY
══════════════════════════════════════════ */
document.addEventListener('DOMContentLoaded', () => {

  /* ── Inject photos ── */
  document.querySelectorAll('.profile-img').forEach(img => img.src = PHOTO);

  /* ── Custom cursor ── */
  initCursor();

  /* ── Navbar ── */
  initNav();

  /* ── Mobile menu ── */
  initMobileMenu();

  /* ── Skills tabs ── */
  initSkillsTabs();

  /* ── Scroll reveal ── */
  initScrollReveal();

  /* ── Back to top ── */
  initBackToTop();

  /* ── Contact form ── */
  initContactForm();

  /* ── Typing effect in hero ── */
  initTyping();

  /* ── Counter animation ── */
  initCounters();

});

/* ══════════════════════════════════════════
   CURSOR
══════════════════════════════════════════ */
function initCursor() {
  const dot   = document.getElementById('cursor');
  const ring  = document.getElementById('cursorRing');
  if (!dot || !ring) return;

  let mx = 0, my = 0, rx = 0, ry = 0;

  document.addEventListener('mousemove', e => {
    mx = e.clientX; my = e.clientY;
    dot.style.left = mx + 'px';
    dot.style.top  = my + 'px';
  });

  (function lerp() {
    rx += (mx - rx) * 0.13;
    ry += (my - ry) * 0.13;
    ring.style.left = rx + 'px';
    ring.style.top  = ry + 'px';
    requestAnimationFrame(lerp);
  })();

  /* Scale ring on interactive elements */
  const hoverEls = document.querySelectorAll(
    'a, button, .proj-card, .edu-card, .gh-repo, .snav, .ci-row, .tech-chip'
  );
  hoverEls.forEach(el => {
    el.addEventListener('mouseenter', () => ring.classList.add('hovered'));
    el.addEventListener('mouseleave', () => ring.classList.remove('hovered'));
  });
}

/* ══════════════════════════════════════════
   NAVBAR
══════════════════════════════════════════ */
function initNav() {
  const nav = document.getElementById('nav');
  if (!nav) return;

  /* Shrink on scroll */
  window.addEventListener('scroll', () => {
    nav.classList.toggle('scrolled', window.scrollY > 60);
  }, { passive: true });

  /* Active link highlight */
  const sections  = document.querySelectorAll('section[id]');
  const navLinks  = document.querySelectorAll('.nav-links a');

  window.addEventListener('scroll', () => {
    let current = '';
    sections.forEach(s => {
      if (window.scrollY >= s.offsetTop - 150) current = s.id;
    });
    navLinks.forEach(a => {
      a.classList.toggle('active', a.getAttribute('href') === '#' + current);
    });
  }, { passive: true });
}

/* ══════════════════════════════════════════
   MOBILE MENU
══════════════════════════════════════════ */
function initMobileMenu() {
  const hbg     = document.getElementById('hamburger');
  const mobNav  = document.getElementById('mobNav');
  const mobClose= document.getElementById('mobClose');
  if (!hbg || !mobNav) return;

  function openMenu()  { mobNav.classList.add('open');    hbg.classList.add('open');    document.body.style.overflow = 'hidden'; }
  function closeMenu() { mobNav.classList.remove('open'); hbg.classList.remove('open'); document.body.style.overflow = ''; }

  hbg.addEventListener('click', openMenu);
  mobClose && mobClose.addEventListener('click', closeMenu);
  document.querySelectorAll('.mob-nav a').forEach(l => l.addEventListener('click', closeMenu));
}

/* ══════════════════════════════════════════
   SKILLS TABS
══════════════════════════════════════════ */
function initSkillsTabs() {
  const tabs   = document.querySelectorAll('.snav');
  const panels = document.querySelectorAll('.spanel');

  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      tabs.forEach(t => t.classList.remove('active'));
      panels.forEach(p => p.classList.remove('active'));
      tab.classList.add('active');

      const target = document.getElementById('sp-' + tab.dataset.tab);
      if (!target) return;
      target.classList.add('active');

      /* Re-animate bars */
      target.querySelectorAll('.skill-fill').forEach(bar => {
        bar.style.width = '0';
        setTimeout(() => { bar.style.width = bar.dataset.w + '%'; }, 80);
      });
    });
  });
}

/* Animate skill bars when scrolled into view */
function animateBarsInPanel(panelId) {
  const panel = document.getElementById(panelId);
  if (!panel) return;
  panel.querySelectorAll('.skill-fill').forEach(bar => {
    if (bar.style.width === '0px' || bar.style.width === '' || bar.style.width === '0') {
      setTimeout(() => { bar.style.width = bar.dataset.w + '%'; }, 200);
    }
  });
}

/* ══════════════════════════════════════════
   SCROLL REVEAL
══════════════════════════════════════════ */
function initScrollReveal() {
  const items = document.querySelectorAll('.sr');

  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('vis');
        /* Trigger skill bars if inside a panel */
        entry.target.querySelectorAll('.skill-fill').forEach(bar => {
          setTimeout(() => { bar.style.width = bar.dataset.w + '%'; }, 280);
        });
        if (entry.target.closest('#skills')) {
          const activePanel = document.querySelector('.spanel.active');
          if (activePanel) animateBarsInPanel(activePanel.id);
        }
      }
    });
  }, { threshold: 0.1 });

  items.forEach(el => observer.observe(el));

  /* Immediately animate first skill panel after load */
  setTimeout(() => animateBarsInPanel('sp-frontend'), 800);
}

/* ══════════════════════════════════════════
   BACK TO TOP
══════════════════════════════════════════ */
function initBackToTop() {
  const btn = document.getElementById('backTop');
  if (!btn) return;

  window.addEventListener('scroll', () => {
    btn.classList.toggle('show', window.scrollY > 500);
  }, { passive: true });

  btn.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
}

/* ══════════════════════════════════════════
   CONTACT FORM
══════════════════════════════════════════ */
function initContactForm() {
  const form    = document.getElementById('contactForm');
  const success = document.getElementById('formSuccess');
  const btn     = document.getElementById('submitBtn');
  if (!form) return;

  btn.addEventListener('click', () => {
    const fname = document.getElementById('fname').value.trim();
    const email = document.getElementById('femail').value.trim();
    const msg   = document.getElementById('fmessage').value.trim();

    if (!fname || !email || !msg) {
      shakeForm(form);
      showFormAlert('Please fill in your name, email and message.');
      return;
    }
    if (!isValidEmail(email)) {
      shakeForm(form);
      showFormAlert('Please enter a valid email address.');
      return;
    }

    /* Simulate send */
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Sending...';
    btn.disabled  = true;
    setTimeout(() => {
      form.style.display = 'none';
      if (success) success.style.display = 'block';
    }, 1200);
  });
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}
function shakeForm(el) {
  el.style.animation = 'shake 0.4s ease';
  setTimeout(() => { el.style.animation = ''; }, 450);
}
function showFormAlert(msg) {
  /* Simple inline alert instead of browser alert */
  let alert = document.getElementById('formAlert');
  if (!alert) {
    alert = document.createElement('div');
    alert.id = 'formAlert';
    alert.style.cssText = `
      background: rgba(218,0,55,0.12); border:1px solid rgba(218,0,55,0.3);
      border-radius:8px; padding:0.75rem 1rem; font-size:0.85rem;
      color:#ff8fa3; margin-top:0.8rem; font-family:'Plus Jakarta Sans',sans-serif;
    `;
    document.getElementById('contactForm').appendChild(alert);
  }
  alert.textContent = msg;
  setTimeout(() => { alert.textContent = ''; }, 3000);
}

